SELECT

FROM wf_agent a
 1=1

        AND a.id = #{id}


        AND a.tenant_id = #{tenantId}


        AND a.process_def_id = #{processDefId}



        AND a.task_def_key = #{taskDefKey}



        AND a.effect_ind = #{effectInd}



        AND a.type = #{type}


        AND a.trust_user = #{trustUser}



        AND a.agent_user =#{agentUser}



        AND a.trust_type =#{trustType}



        AND a.trust_type  IN

            #{itemType}

SELECT

FROM wf_agent a
where id = #{id}

SELECT b.type, b.TRUST_USER FROM ACT_RU_IDENTITYLINK a, WF_AGENT b WHERE a.PROC_DEF_ID_ = b.PROCESS_DEF_ID AND b.TASK_DEF_KEY IS NULL AND ( ( a.USER_ID_ = b.TRUST_USER
AND b.type='user' and b.agent_user =#{userId}
) OR ( b.TRUST_USER = a.ROLE_CODE
AND b.agent_user in
#{roleCd}
) OR ( b.TRUST_USER = a.ORG_CODE
AND b.agent_user in
#{orgCd}
) ) AND b.AGENT_TYPE ='0' AND b.TENANT_ID =#{tenantId} and a.TENANT_ID = b.TENANT_ID
AND trunc(b.START_DATE) <= trunc(sysdate) AND b.END_DATE > sysdate
AND STR_TO_DATE(b.START_DATE,'%Y-%m-%d %H:%i:%s') <= STR_TO_DATE(CURDATE(),'%Y-%m-%d %H:%i:%s') AND b.END_DATE > now()

SELECT b.type, b.TRUST_USER FROM ACT_RU_IDENTITYLINK a, WF_AGENT b WHERE a.PROC_DEF_ID_ = b.PROCESS_DEF_ID AND A.TASK_DEF_KEY = b.TASK_DEF_KEY AND ( ( a.USER_ID_ = b.TRUST_USER
AND b.type='user' and b.agent_user =#{userId}
) OR ( b.TRUST_USER = a.ROLE_CODE
AND b.agent_user in
#{roleCd}
) OR ( b.TRUST_USER = a.ORG_CODE
AND b.agent_user in
#{orgCd}
) ) AND b.AGENT_TYPE ='0' AND b.TENANT_ID =#{tenantId} and a.TENANT_ID = b.TENANT_ID
AND trunc(B.START_DATE) <= trunc(sysdate) AND B.END_DATE > sysdate
AND STR_TO_DATE(B.START_DATE,'%Y-%m-%d %H:%i:%s') <= STR_TO_DATE(CURDATE(),'%Y-%m-%d %H:%i:%s') AND B.END_DATE > now()

SELECT b.type, b.TRUST_USER FROM ACT_RU_IDENTITYLINK a, WF_AGENT b WHERE b.AGENT_TYPE ='1' AND ( ( a.USER_ID_ = b.TRUST_USER
AND b.type='user' and b.agent_user =#{userId}
) OR ( b.TRUST_USER = a.ROLE_CODE and b.type='role'
AND b.agent_user in
#{roleCd}
) OR ( b.TRUST_USER = a.ORG_CODE and b.type='org'
AND b.agent_user in
#{orgCd}
) ) AND b.TENANT_ID =#{tenantId} and a.TENANT_ID = b.TENANT_ID
AND B.START_DATE < sysdate AND B.END_DATE > sysdate
AND B.START_DATE < now() AND B.END_DATE > now()

SELECT
a.PROCESS_DEF_ID,
a.TASK_DEF_KEY,
a.AGENT_USER,
a.TRUST_USER,
a.TYPE
FROM
WF_AGENT  a
where   a.TENANT_ID =#{tenantId}
DATE_FORMAT( NOW(), '%Y-%m-%d %h:%i %p' )


       AND to_char(a.START_DATE,'yyyy-mm-dd') <= to_char(sysdate,'yyyy-mm-dd')  AND a.END_DATE > sysdate




       AND DATE_FORMAT(a.START_DATE, '%Y-%m-%d') <= DATE_FORMAT(now(), '%Y-%m-%d')  AND a.END_DATE > now()




    AND a.agent_user =#{agentUser}



    and  a.agent_user  in

        #{user}




    AND a.effect_ind = #{effectInd}



    AND a.trust_user =#{trustUser}



    AND a.type = #{type}



    AND a.trust_type = #{trustType}

SELECT a.id, a.PROCESS_DEF_ID, a.TASK_DEF_KEY, a.AGENT_USER, a.TRUST_USER, a.effect_ind, a.TYPE, a.end_date FROM WF_AGENT a where a.TENANT_ID =#{tenantId}
AND trunc(a.START_DATE) <= trunc(sysdate) AND a.END_DATE > sysdate
AND STR_TO_DATE(a.START_DATE,'%Y-%m-%d %H:%i:%s') <= STR_TO_DATE(CURDATE(),'%Y-%m-%d %H:%i:%s') AND a.END_DATE > now()
AND a.TRUST_USER =#{trustUser}
AND a.PROCESS_DEF_ID =#{processDefId}
AND a.TASK_DEF_KEY =#{taskDefKey}
